NEW_FILES = {
    "supabase/migrations/0007_add_tournaments_table.sql": "-- Flere turneringer (admin kan nå lage en LISTE av turneringer, se\n-- app/admin/koder/turneringer/TournamentsManager.tsx) i stedet for ett delt\n-- sett med innstillinger (de tre gamle \"tournament*\"-nøklene i\n-- app_settings – de ligger fortsatt i tabellen, men brukes ikke lenger, og\n-- kan fjernes manuelt om ønskelig).\ncreate table if not exists tournaments (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  code text not null,\n  active boolean not null default false,\n  expires_at date,\n  created_at timestamptz not null default now()\n);\n\n-- Hvilken turnering en gitt booking hører til (kun satt for en\n-- turneringsbooking, se opponent_name i 0006_add_tournament_fields.sql) –\n-- \"on delete set null\" slik at en kamp ikke forsvinner fra historikken om\n-- admin senere sletter selve turneringen.\nalter table booking_groups\n  add column if not exists tournament_id uuid references tournaments(id) on delete set null;\n",
    "lib/settings/tournament.ts": "import \"server-only\";\nimport { getRepository } from \"@/lib/db\";\nimport { todayInClubTimeZone } from \"@/lib/slots\";\nimport type { Tournament } from \"@/lib/db/types\";\n\n/**\n * Turneringsfunksjon: admin kan nå lage FLERE turneringer (se\n * app/admin/koder/turneringer/TournamentsManager.tsx + Tournament i\n * lib/db/types.ts), hver med sin egen kode/av-på-bryter/utløpsdato – i\n * stedet for ETT delt sett med innstillinger (den gamle modellen denne fila\n * tidligere implementerte selv, med de tre nøklene tournamentCode/\n * tournamentActive/tournamentExpiresAt i app_settings). Denne fila er derfor\n * nå bare selve KODE-OPPSLAGET på tvers av alle turneringer, brukt BÅDE av\n * den offentlige \"er denne koden gyldig akkurat nå\"-sjekken (se\n * app/api/squash/tournament-code/route.ts, kalt mens kunden skriver) OG av\n * selve bookingen (se app/api/squash/bookings/route.ts, sjekket på nytt\n * server-side – aldri stol på klientens egen \"gyldig kode\"-sjekk alene).\n */\n\n/**\n * Finner den (ene) aktive, ikke-utløpte turneringen hvis kode matcher –\n * uten hensyn til store/små bokstaver eller ekstra mellomrom, siden en\n * spiller lett kan skrive koden litt annerledes enn admin gjorde. Admin-\n * API-et (app/api/admin/tournaments/route.ts) hindrer to turneringer i å\n * dele samme kode, så matchet bør alltid være unikt – finner vi likevel\n * flere (f.eks. gammel data), brukes ganske enkelt den første.\n */\nexport async function findValidTournamentByCode(inputCode: string): Promise<Tournament | null> {\n  const trimmed = inputCode.trim();\n  if (!trimmed) return null;\n\n  const repo = await getRepository();\n  const tournaments = await repo.listTournaments();\n  const today = todayInClubTimeZone();\n\n  return (\n    tournaments.find(\n      (t) => t.active && (!t.expiresAt || today <= t.expiresAt) && t.code.trim().toLowerCase() === trimmed.toLowerCase()\n    ) ?? null\n  );\n}\n\nexport async function isTournamentCodeValid(inputCode: string): Promise<boolean> {\n  return (await findValidTournamentByCode(inputCode)) !== null;\n}\n",
    "app/api/admin/tournaments/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { getRepository } from \"@/lib/db\";\nimport { isValidDateString } from \"@/lib/settings/openingHours\";\n\nexport const dynamic = \"force-dynamic\";\n\n/**\n * GET  /api/admin/tournaments – lister alle turneringer (nyeste først).\n * POST /api/admin/tournaments – opprett en ny turnering.\n *\n * Beskyttet av middleware.ts – IKKE i noen av BOOKINGS_ONLY_ALLOWED_*-listene\n * der, så en begrenset (\"bookings_only\") administrator nektes automatisk,\n * akkurat som resten av Oppsett/Vipps/Utseende/Koder.\n */\nexport async function GET() {\n  try {\n    const repo = await getRepository();\n    const tournaments = await repo.listTournaments();\n    return NextResponse.json({ tournaments });\n  } catch (err) {\n    return NextResponse.json(\n      { error: err instanceof Error ? err.message : \"Kunne ikke hente turneringer.\" },\n      { status: 500 }\n    );\n  }\n}\n\ninterface CreateBody {\n  name?: string;\n  code?: string;\n  active?: boolean;\n  expiresAt?: string | null;\n}\n\nexport async function POST(request: NextRequest) {\n  let body: CreateBody;\n  try {\n    body = (await request.json()) as CreateBody;\n  } catch {\n    return NextResponse.json({ error: \"Ugyldig forespørsel.\" }, { status: 400 });\n  }\n\n  const name = body.name?.trim() ?? \"\";\n  const code = body.code?.trim() ?? \"\";\n  const active = body.active === true;\n  const expiresAt = body.expiresAt ? body.expiresAt : null;\n\n  if (name.length < 2 || name.length > 100) {\n    return NextResponse.json({ error: \"Navn må være mellom 2 og 100 tegn.\" }, { status: 400 });\n  }\n  if (!code) {\n    return NextResponse.json({ error: \"Skriv inn en kode for turneringen.\" }, { status: 400 });\n  }\n  if (expiresAt !== null && !isValidDateString(expiresAt)) {\n    return NextResponse.json({ error: \"Ugyldig utløpsdato (forventet format ÅÅÅÅ-MM-DD).\" }, { status: 400 });\n  }\n\n  try {\n    const repo = await getRepository();\n    const existing = await repo.listTournaments();\n    const codeLower = code.toLowerCase();\n    if (existing.some((t) => t.code.trim().toLowerCase() === codeLower)) {\n      return NextResponse.json({ error: \"En annen turnering bruker allerede denne koden.\" }, { status: 400 });\n    }\n\n    const tournament = await repo.createTournament({ name, code, active, expiresAt });\n    return NextResponse.json({ tournament });\n  } catch (err) {\n    return NextResponse.json(\n      { error: err instanceof Error ? err.message : \"Kunne ikke opprette turnering.\" },\n      { status: 400 }\n    );\n  }\n}\n",
    "app/api/admin/tournaments/[id]/route.ts": "import { NextRequest, NextResponse } from \"next/server\";\nimport { getRepository } from \"@/lib/db\";\nimport { isValidDateString } from \"@/lib/settings/openingHours\";\n\nexport const dynamic = \"force-dynamic\";\n\ninterface PatchBody {\n  name?: string;\n  code?: string;\n  active?: boolean;\n  expiresAt?: string | null;\n}\n\n/**\n * PATCH  /api/admin/tournaments/[id] – endre navn/kode/av-på/utløpsdato.\n * DELETE /api/admin/tournaments/[id] – slett turneringen (kamper allerede\n *        booket med den beholdes, se tournament_id i migrasjonen – \"on\n *        delete set null\").\n */\nexport async function PATCH(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {\n  const { id } = await params;\n  let body: PatchBody;\n  try {\n    body = (await request.json()) as PatchBody;\n  } catch {\n    return NextResponse.json({ error: \"Ugyldig forespørsel.\" }, { status: 400 });\n  }\n\n  const patch: { name?: string; code?: string; active?: boolean; expiresAt?: string | null } = {};\n\n  if (body.name !== undefined) {\n    const name = body.name.trim();\n    if (name.length < 2 || name.length > 100) {\n      return NextResponse.json({ error: \"Navn må være mellom 2 og 100 tegn.\" }, { status: 400 });\n    }\n    patch.name = name;\n  }\n\n  if (body.code !== undefined) {\n    const code = body.code.trim();\n    if (!code) {\n      return NextResponse.json({ error: \"Skriv inn en kode for turneringen.\" }, { status: 400 });\n    }\n    patch.code = code;\n  }\n\n  if (body.active !== undefined) patch.active = body.active === true;\n\n  if (body.expiresAt !== undefined) {\n    const expiresAt = body.expiresAt ? body.expiresAt : null;\n    if (expiresAt !== null && !isValidDateString(expiresAt)) {\n      return NextResponse.json({ error: \"Ugyldig utløpsdato (forventet format ÅÅÅÅ-MM-DD).\" }, { status: 400 });\n    }\n    patch.expiresAt = expiresAt;\n  }\n\n  try {\n    const repo = await getRepository();\n\n    if (patch.code !== undefined) {\n      const codeLower = patch.code.toLowerCase();\n      const existing = await repo.listTournaments();\n      if (existing.some((t) => t.id !== id && t.code.trim().toLowerCase() === codeLower)) {\n        return NextResponse.json({ error: \"En annen turnering bruker allerede denne koden.\" }, { status: 400 });\n      }\n    }\n\n    const tournament = await repo.updateTournament(id, patch);\n    return NextResponse.json({ tournament });\n  } catch (err) {\n    return NextResponse.json(\n      { error: err instanceof Error ? err.message : \"Kunne ikke oppdatere turnering.\" },\n      { status: 400 }\n    );\n  }\n}\n\nexport async function DELETE(_request: NextRequest, { params }: { params: Promise<{ id: string }> }) {\n  const { id } = await params;\n  try {\n    const repo = await getRepository();\n    await repo.deleteTournament(id);\n    return NextResponse.json({ ok: true });\n  } catch (err) {\n    return NextResponse.json(\n      { error: err instanceof Error ? err.message : \"Kunne ikke slette turnering.\" },\n      { status: 400 }\n    );\n  }\n}\n",
    "app/admin/koder/KoderTabs.tsx": "\"use client\";\n\nimport styles from \"../admin.module.css\";\n\nconst SUB_TABS = [\n  { key: \"turneringer\", label: \"Turneringer\", href: \"/admin/koder/turneringer\" },\n  { key: \"klippekort\", label: \"Klippekort\", href: \"/admin/koder/klippekort\" },\n] as const;\n\nexport type KoderTabKey = (typeof SUB_TABS)[number][\"key\"];\n\n/**\n * Underfane-linje for \"Koder\" (se TABS i AdminNav.tsx) – Turneringer og\n * Klippekort er to separate sider/komponenter, men vises som to faner under\n * samme hovedfane i venstremenyen. Rendres av hver underside selv (se\n * turneringer/TournamentsManager.tsx og klippekort/KlippekortManager.tsx),\n * rett over sidens egen <h1>.\n */\nexport default function KoderTabs({ active }: { active: KoderTabKey }) {\n  return (\n    <div className={styles.subTabBar}>\n      {SUB_TABS.map((tab) => (\n        <a\n          key={tab.key}\n          href={tab.href}\n          className={`${styles.subTabLink} ${tab.key === active ? styles.subTabLinkActive : \"\"}`}\n          aria-current={tab.key === active ? \"page\" : undefined}\n        >\n          {tab.label}\n        </a>\n      ))}\n    </div>\n  );\n}\n",
    "app/admin/koder/page.tsx": "import { redirect } from \"next/navigation\";\n\n/**\n * \"/admin/koder\" i seg selv har ikke noe eget innhold – Koder-fanen (se\n * AdminNav.tsx) peker hit, og siden videresender rett til Turneringer-\n * underfanen (se koder/turneringer/page.tsx), som er den vi viser som\n * standard.\n */\nexport default function AdminKoderPage() {\n  redirect(\"/admin/koder/turneringer\");\n}\n",
    "app/admin/koder/turneringer/page.tsx": "import TournamentsManager from \"./TournamentsManager\";\n\nexport const metadata = { title: \"Turneringer – Squashbooking admin\" };\n\nexport default function AdminTournamentsPage() {\n  return <TournamentsManager />;\n}\n",
    "app/admin/koder/klippekort/page.tsx": "import KlippekortManager from \"./KlippekortManager\";\n\nexport const metadata = { title: \"Klippekort – Squashbooking admin\" };\n\nexport default function AdminKlippekortPage() {\n  return <KlippekortManager />;\n}\n",
    "app/admin/koder/klippekort/KlippekortManager.tsx": "\"use client\";\n\nimport styles from \"../../admin.module.css\";\nimport AdminNav from \"../../AdminNav\";\nimport KoderTabs from \"../KoderTabs\";\n\n/**\n * \"Klippekort\" – underfane under Koder (se app/admin/koder/KoderTabs.tsx).\n * Foreløpig en plassholder: selve kjøpsflyten (kunden velger antall kamper,\n * betaler med Vipps, får en kode generert av ordkombinasjoner, sendt på\n * e-post) bygges i en EGEN runde, siden den trenger en ny kjøpsside, en\n * kodegenerator og e-postutsending (e-posttjeneste ikke valgt ennå – avtales\n * i chatten med Helge). Denne siden finnes likevel allerede nå, slik at\n * \"Koder\"-fanen har begge underfanene synlige på plass.\n */\nexport default function KlippekortManager() {\n  return (\n    <>\n      <AdminNav active=\"koder\" />\n      <main className={styles.page}>\n        <div className={styles.tabPanel}>\n          <KoderTabs active=\"klippekort\" />\n          <h1 className={styles.title}>Klippekort</h1>\n          <p className={styles.subtitle}>\n            Kunder skal kunne kjøpe et valgfritt antall kamper til en fast pris per kamp, og få en kode (bygget av\n            ordkombinasjoner) de kan bruke selv eller gi bort – delt opp i en egen runde siden den trenger en egen\n            kjøpsside med Vipps og e-postutsending.\n          </p>\n          <div className={styles.card}>\n            <p className={styles.bookingMeta}>Kommer snart – under utvikling.</p>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n",
    "app/admin/koder/turneringer/TournamentsManager.tsx": "\"use client\";\n\nimport { useEffect, useState, type FormEvent } from \"react\";\nimport styles from \"../../admin.module.css\";\nimport { formatOslo } from \"@/lib/formatting\";\nimport AdminNav from \"../../AdminNav\";\nimport KoderTabs from \"../KoderTabs\";\n\ninterface Tournament {\n  id: string;\n  name: string;\n  code: string;\n  active: boolean;\n  expiresAt: string | null;\n  createdAt: string;\n}\n\ninterface SlotInfo {\n  startTime: string;\n  endTime: string;\n}\n\ntype MatchStatus = \"pending\" | \"confirmed\" | \"cancelled\" | \"expired\";\n\ninterface TournamentMatch {\n  id: string;\n  status: MatchStatus;\n  customerName: string;\n  opponentName: string | null;\n  tournamentId: string | null;\n  slots: SlotInfo[];\n}\n\nconst STATUS_LABEL: Record<MatchStatus, string> = {\n  pending: \"Venter\",\n  confirmed: \"Bekreftet\",\n  cancelled: \"Avlyst\",\n  expired: \"Utløpt\",\n};\n\ninterface TournamentFormState {\n  name: string;\n  code: string;\n  active: boolean;\n  expiresAt: string;\n}\n\nconst EMPTY_FORM: TournamentFormState = { name: \"\", code: \"\", active: false, expiresAt: \"\" };\n\n/**\n * \"Turneringer\" – underfane under Koder (se app/admin/koder/KoderTabs.tsx).\n * Admin kan nå lage FLERE turneringer (i stedet for ett delt sett med\n * innstillinger, se den gamle app/admin/turnering/TournamentManager.tsx) –\n * hver med sin egen kode/av-på-bryter/utløpsdato, og se/avlyse kampene\n * booket med akkurat DEN turneringen (ekspanderbar liste per rad).\n */\nexport default function TournamentsManager() {\n  const [tournaments, setTournaments] = useState<Tournament[]>([]);\n  const [loadingTournaments, setLoadingTournaments] = useState(true);\n\n  const [creating, setCreating] = useState(false);\n  const [createForm, setCreateForm] = useState<TournamentFormState>(EMPTY_FORM);\n  const [createMessage, setCreateMessage] = useState<{ ok: boolean; text: string } | null>(null);\n  const [savingCreate, setSavingCreate] = useState(false);\n\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [editForm, setEditForm] = useState<TournamentFormState>(EMPTY_FORM);\n  const [editMessage, setEditMessage] = useState<{ ok: boolean; text: string } | null>(null);\n  const [savingEdit, setSavingEdit] = useState(false);\n  const [deletingId, setDeletingId] = useState<string | null>(null);\n\n  const [expandedId, setExpandedId] = useState<string | null>(null);\n  const [matches, setMatches] = useState<TournamentMatch[]>([]);\n  const [loadingMatches, setLoadingMatches] = useState(true);\n  const [cancellingId, setCancellingId] = useState<string | null>(null);\n\n  async function loadTournaments() {\n    setLoadingTournaments(true);\n    try {\n      const res = await fetch(\"/api/admin/tournaments\", { cache: \"no-store\" });\n      const data = (await res.json()) as { tournaments: Tournament[] };\n      setTournaments(data.tournaments ?? []);\n    } finally {\n      setLoadingTournaments(false);\n    }\n  }\n\n  async function loadMatches() {\n    setLoadingMatches(true);\n    try {\n      const res = await fetch(\"/api/admin/bookings\", { cache: \"no-store\" });\n      const data = (await res.json()) as { bookings: TournamentMatch[] };\n      // Adminpanelets vanlige \"alle bookinger\"-endepunkt (se\n      // app/api/admin/bookings/route.ts) – en turneringskamp er bare en\n      // enkeltbooking som i tillegg har opponentName satt (se\n      // lib/db/types.ts), så vi filtrerer på det her, og videre på\n      // tournamentId per turnering nedenfor.\n      setMatches((data.bookings ?? []).filter((b) => !!b.opponentName));\n    } finally {\n      setLoadingMatches(false);\n    }\n  }\n\n  useEffect(() => {\n    loadTournaments();\n    loadMatches();\n  }, []);\n\n  async function handleCreate(e: FormEvent) {\n    e.preventDefault();\n    setSavingCreate(true);\n    setCreateMessage(null);\n    try {\n      const res = await fetch(\"/api/admin/tournaments\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ ...createForm, expiresAt: createForm.expiresAt || null }),\n      });\n      const data = (await res.json()) as { error?: string };\n      if (!res.ok) {\n        setCreateMessage({ ok: false, text: data.error ?? \"Kunne ikke opprette turnering.\" });\n        return;\n      }\n      setCreateForm(EMPTY_FORM);\n      setCreating(false);\n      setCreateMessage(null);\n      await loadTournaments();\n    } catch {\n      setCreateMessage({ ok: false, text: \"Kunne ikke opprette turnering akkurat nå.\" });\n    } finally {\n      setSavingCreate(false);\n    }\n  }\n\n  function startEdit(t: Tournament) {\n    setEditingId(t.id);\n    setEditForm({ name: t.name, code: t.code, active: t.active, expiresAt: t.expiresAt ?? \"\" });\n    setEditMessage(null);\n  }\n\n  function cancelEdit() {\n    setEditingId(null);\n    setEditMessage(null);\n  }\n\n  async function handleSaveEdit(e: FormEvent) {\n    e.preventDefault();\n    if (!editingId) return;\n    setSavingEdit(true);\n    setEditMessage(null);\n    try {\n      const res = await fetch(`/api/admin/tournaments/${editingId}`, {\n        method: \"PATCH\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ ...editForm, expiresAt: editForm.expiresAt || null }),\n      });\n      const data = (await res.json()) as { error?: string };\n      if (!res.ok) {\n        setEditMessage({ ok: false, text: data.error ?? \"Kunne ikke lagre.\" });\n        return;\n      }\n      setEditingId(null);\n      await loadTournaments();\n    } catch {\n      setEditMessage({ ok: false, text: \"Kunne ikke lagre akkurat nå.\" });\n    } finally {\n      setSavingEdit(false);\n    }\n  }\n\n  async function handleDelete(t: Tournament) {\n    if (\n      !window.confirm(\n        `Slette turneringen \"${t.name}\"? Dette kan ikke angres. Kamper som allerede er booket med den, beholdes.`\n      )\n    )\n      return;\n\n    setDeletingId(t.id);\n    try {\n      const res = await fetch(`/api/admin/tournaments/${t.id}`, { method: \"DELETE\" });\n      const data = (await res.json().catch(() => ({}))) as { error?: string };\n      if (!res.ok) window.alert(data.error ?? \"Kunne ikke slette turneringen.\");\n      await loadTournaments();\n    } finally {\n      setDeletingId(null);\n    }\n  }\n\n  async function handleCancelMatch(match: TournamentMatch) {\n    const label = `${match.customerName} vs ${match.opponentName}`;\n    if (!window.confirm(`Avlyse \"${label}\"? Dette kan ikke angres.`)) return;\n\n    setCancellingId(match.id);\n    try {\n      const res = await fetch(`/api/admin/bookings/${match.id}`, { method: \"DELETE\" });\n      const data = (await res.json().catch(() => ({}))) as { error?: string };\n      if (!res.ok) window.alert(data.error ?? \"Kunne ikke avlyse kampen.\");\n      await loadMatches();\n    } finally {\n      setCancellingId(null);\n    }\n  }\n\n  return (\n    <>\n      <AdminNav active=\"koder\" />\n      <main className={styles.page}>\n        <div className={styles.tabPanel}>\n          <KoderTabs active=\"turneringer\" />\n          <h1 className={styles.title}>Turneringer</h1>\n          <p className={styles.subtitle}>\n            Hver turnering har sin egen kode – spillere som skriver inn en gyldig, aktiv kode når de booker en\n            enkelttime, slipper å betale, og skriver i stedet inn hvem de møter.\n          </p>\n\n          <div className={styles.card}>\n            <div style={{ display: \"flex\", justifyContent: \"space-between\", alignItems: \"center\", flexWrap: \"wrap\", gap: 8 }}>\n              <h2 style={{ marginTop: 0, fontSize: \"1.1rem\" }}>Alle turneringer</h2>\n              {!creating && (\n                <button\n                  type=\"button\"\n                  className={styles.secondaryButton}\n                  onClick={() => {\n                    setCreating(true);\n                    setCreateForm(EMPTY_FORM);\n                    setCreateMessage(null);\n                  }}\n                >\n                  + Ny turnering\n                </button>\n              )}\n            </div>\n\n            {creating && (\n              <form onSubmit={handleCreate} className={styles.form} style={{ marginTop: 12, marginBottom: 16 }}>\n                <div className={styles.formRow}>\n                  <label htmlFor=\"new-tournament-name\">Navn</label>\n                  <input\n                    id=\"new-tournament-name\"\n                    type=\"text\"\n                    maxLength={100}\n                    value={createForm.name}\n                    onChange={(e) => setCreateForm((f) => ({ ...f, name: e.target.value }))}\n                    placeholder=\"F.eks. Høstturneringen 2026\"\n                  />\n                </div>\n                <div className={styles.formRow}>\n                  <label htmlFor=\"new-tournament-code\">Kode spillerne skriver inn</label>\n                  <input\n                    id=\"new-tournament-code\"\n                    type=\"text\"\n                    maxLength={50}\n                    value={createForm.code}\n                    onChange={(e) => setCreateForm((f) => ({ ...f, code: e.target.value }))}\n                    placeholder=\"F.eks. HOST2026\"\n                  />\n                </div>\n                <label className={styles.checkboxOption}>\n                  <input\n                    type=\"checkbox\"\n                    checked={createForm.active}\n                    onChange={(e) => setCreateForm((f) => ({ ...f, active: e.target.checked }))}\n                  />\n                  Koden er aktiv (spillere kan bruke den nå)\n                </label>\n                <div className={styles.formRow}>\n                  <label htmlFor=\"new-tournament-expires\">Utløpsdato (valgfritt)</label>\n                  <input\n                    id=\"new-tournament-expires\"\n                    type=\"date\"\n                    value={createForm.expiresAt}\n                    onChange={(e) => setCreateForm((f) => ({ ...f, expiresAt: e.target.value }))}\n                  />\n                  <p className={styles.bookingMeta}>La stå tom for ingen utløpsdato.</p>\n                </div>\n\n                {createMessage && (\n                  <p className={createMessage.ok ? styles.success : styles.error}>{createMessage.text}</p>\n                )}\n\n                <div style={{ display: \"flex\", gap: 8 }}>\n                  <button type=\"submit\" className={styles.submitButton} disabled={savingCreate}>\n                    {savingCreate ? \"Lagrer …\" : \"Opprett\"}\n                  </button>\n                  <button type=\"button\" className={styles.secondaryButton} onClick={() => setCreating(false)}>\n                    Avbryt\n                  </button>\n                </div>\n              </form>\n            )}\n\n            {loadingTournaments ? (\n              <p>Laster …</p>\n            ) : tournaments.length === 0 ? (\n              <p className={styles.bookingMeta}>Ingen turneringer opprettet ennå.</p>\n            ) : (\n              <div className={styles.userList}>\n                {tournaments.map((t) => (\n                  <div key={t.id}>\n                    {editingId === t.id ? (\n                      <form\n                        onSubmit={handleSaveEdit}\n                        className={styles.form}\n                        style={{ border: \"1px solid var(--border)\", borderRadius: 10, padding: 12 }}\n                      >\n                        <div className={styles.formRow}>\n                          <label htmlFor=\"edit-tournament-name\">Navn</label>\n                          <input\n                            id=\"edit-tournament-name\"\n                            type=\"text\"\n                            maxLength={100}\n                            value={editForm.name}\n                            onChange={(e) => setEditForm((f) => ({ ...f, name: e.target.value }))}\n                          />\n                        </div>\n                        <div className={styles.formRow}>\n                          <label htmlFor=\"edit-tournament-code\">Kode spillerne skriver inn</label>\n                          <input\n                            id=\"edit-tournament-code\"\n                            type=\"text\"\n                            maxLength={50}\n                            value={editForm.code}\n                            onChange={(e) => setEditForm((f) => ({ ...f, code: e.target.value }))}\n                          />\n                        </div>\n                        <label className={styles.checkboxOption}>\n                          <input\n                            type=\"checkbox\"\n                            checked={editForm.active}\n                            onChange={(e) => setEditForm((f) => ({ ...f, active: e.target.checked }))}\n                          />\n                          Koden er aktiv (spillere kan bruke den nå)\n                        </label>\n                        <div className={styles.formRow}>\n                          <label htmlFor=\"edit-tournament-expires\">Utløpsdato (valgfritt)</label>\n                          <input\n                            id=\"edit-tournament-expires\"\n                            type=\"date\"\n                            value={editForm.expiresAt}\n                            onChange={(e) => setEditForm((f) => ({ ...f, expiresAt: e.target.value }))}\n                          />\n                          <p className={styles.bookingMeta}>La stå tom for ingen utløpsdato.</p>\n                        </div>\n\n                        {editMessage && (\n                          <p className={editMessage.ok ? styles.success : styles.error}>{editMessage.text}</p>\n                        )}\n\n                        <div style={{ display: \"flex\", gap: 8 }}>\n                          <button type=\"submit\" className={styles.submitButton} disabled={savingEdit}>\n                            {savingEdit ? \"Lagrer …\" : \"Lagre\"}\n                          </button>\n                          <button type=\"button\" className={styles.secondaryButton} onClick={cancelEdit}>\n                            Avbryt\n                          </button>\n                        </div>\n                      </form>\n                    ) : (\n                      <div className={styles.userRow}>\n                        <div>\n                          <strong>{t.name}</strong>\n                          <div className={styles.bookingMeta}>\n                            Kode: {t.code} · {t.active ? \"Aktiv\" : \"Ikke aktiv\"}\n                            {t.expiresAt ? ` · Utløper ${t.expiresAt}` : \"\"}\n                          </div>\n                        </div>\n                        <div style={{ display: \"flex\", gap: 6, flexWrap: \"wrap\" }}>\n                          <button\n                            type=\"button\"\n                            className={styles.secondaryButton}\n                            onClick={() => setExpandedId(expandedId === t.id ? null : t.id)}\n                          >\n                            {expandedId === t.id ? \"Skjul kamper\" : \"Vis kamper\"}\n                          </button>\n                          <button type=\"button\" className={styles.secondaryButton} onClick={() => startEdit(t)}>\n                            Rediger\n                          </button>\n                          <button\n                            type=\"button\"\n                            className={styles.dangerButton}\n                            disabled={deletingId === t.id}\n                            onClick={() => handleDelete(t)}\n                          >\n                            {deletingId === t.id ? \"Sletter …\" : \"Slett\"}\n                          </button>\n                        </div>\n                      </div>\n                    )}\n\n                    {expandedId === t.id && editingId !== t.id && (\n                      <div className={styles.tournamentMatchesPanel}>\n                        {loadingMatches && <p className={styles.bookingMeta}>Laster kamper …</p>}\n                        {!loadingMatches && matches.filter((m) => m.tournamentId === t.id).length === 0 && (\n                          <p className={styles.bookingMeta}>Ingen kamper booket i denne turneringen ennå.</p>\n                        )}\n                        {!loadingMatches && matches.filter((m) => m.tournamentId === t.id).length > 0 && (\n                          <div className={styles.userList}>\n                            {matches\n                              .filter((m) => m.tournamentId === t.id)\n                              .map((m) => (\n                                <div key={m.id} className={styles.userRow}>\n                                  <div>\n                                    <strong>\n                                      {m.customerName} vs {m.opponentName}\n                                    </strong>\n                                    <div className={styles.bookingMeta}>\n                                      {m.slots\n                                        .map((s) => formatOslo(s.startTime, \"EEEE d. MMM yyyy 'kl.' HH:mm\"))\n                                        .join(\", \")}\n                                      {\" · \"}\n                                      {STATUS_LABEL[m.status]}\n                                    </div>\n                                  </div>\n                                  {(m.status === \"pending\" || m.status === \"confirmed\") && (\n                                    <button\n                                      type=\"button\"\n                                      className={styles.dangerButton}\n                                      disabled={cancellingId === m.id}\n                                      onClick={() => handleCancelMatch(m)}\n                                    >\n                                      {cancellingId === m.id ? \"Avlyser …\" : \"Avlys\"}\n                                    </button>\n                                  )}\n                                </div>\n                              ))}\n                          </div>\n                        )}\n                      </div>\n                    )}\n                  </div>\n                ))}\n              </div>\n            )}\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n",
}

DELETE_FILES = [
    "app/admin/turnering/page.tsx",
    "app/admin/turnering/TournamentManager.tsx",
    "app/api/admin/settings/tournament/route.ts",
]


def apply_edit(root, relpath, label, old, new, marker):
    path = os.path.join(root, relpath)
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()

    if marker in text:
        print(f"  = {relpath} / {label}: allerede anvendt, hopper over.")
        return

    count = text.count(old)
    if count != 1:
        print(f"FEIL: {relpath} / {label}: fant 'old' {count} ganger (forventet 1). Filen har endret seg mer enn forventet - avbryter uten å gjette.")
        sys.exit(1)

    text = text.replace(old, new, 1)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
    print(f"  + {relpath} / {label}: OK")


def write_full(root, relpath, content):
    path = os.path.join(root, relpath)
    if os.path.exists(path):
        with open(path, "r", encoding="utf-8") as f:
            if f.read() == content:
                print(f"  = {relpath}: allerede lik, hopper over.")
                return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"  + {relpath}: skrevet.")


def delete_file(root, relpath):
    path = os.path.join(root, relpath)
    if os.path.exists(path):
        os.remove(path)
        print(f"  - {relpath}: slettet.")
    else:
        print(f"  = {relpath}: finnes ikke (allerede slettet), hopper over.")


def main(root, run_typecheck=True):
    print("Anvender edits i eksisterende filer ...")
    for relpath, edits in EDITS.items():
        for label, old, new, marker in edits:
            apply_edit(root, relpath, label, old, new, marker)

    print("Skriver nye filer ...")
    for relpath, content in NEW_FILES.items():
        write_full(root, relpath, content)

    print("Sletter gamle filer som er erstattet ...")
    for relpath in DELETE_FILES:
        delete_file(root, relpath)

    if not run_typecheck:
        return True

    print()
    print("Kjører npm run typecheck ...")
    result = subprocess.run(["npm", "run", "typecheck"], cwd=root)
    if result.returncode != 0:
        print()
        print("TYPECHECK FEILET. Ingenting er rullet tilbake - filene over er endret.")
        print("Lim inn feilmeldingen over til Claude, så fikses det i neste runde.")
        return False

    print()
    print("TYPECHECK OK.")
    print()
    print("Husk:")
    print("  1. git add -A && git commit -m \"...\" && git push")
    print("  2. Lim supabase/migrations/0007_add_tournaments_table.sql inn i Supabase sin SQL Editor og kjor den.")
    return True


if __name__ == "__main__":
    root = os.getcwd()
    ok = main(root, run_typecheck=True)
    sys.exit(0 if ok else 1)
